struct stringx {
    char *chars;
    void *my_buf;
    stringx(const stringx &);
    ~stringx();
};

typedef unsigned int color32;

class Font {
public:
    enum HORIZJUST {
        HORIZJUST_LEFT,
        HORIZJUST_CENTER,
        HORIZJUST_RIGHT
    };
    enum VERTJUST {
        VERTJUST_TOP,
        VERTJUST_CENTER,
        VERTJUST_BOTTOM
    };
};

class TextString {
protected:
    Font *font;
    stringx text;
    float x;
    float y;
    int z;
    Font::HORIZJUST hJustify;
    Font::VERTJUST vJustify;
    bool even_number_spacing;
    int fade;
    float fade_alpha;
    float fade_timer;
    float scale;
    float button_scale;
    bool override_alpha;

public:
    bool checkTime;
    float time;
    bool no_color;
    color32 color;

    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
    virtual void setHJustify(Font::HORIZJUST);
    virtual void setVJustify(Font::VERTJUST);
    virtual void setFont(Font *);
    virtual void setButtonScale(float);
    virtual void numberSpacing(bool);
    virtual void changeText(stringx);
    virtual void changeScale(float);
    virtual void changePos(float, float);
    virtual void changeX(float);
    virtual void changeY(float);
    virtual void changeZ(int);
    virtual void ChangeFade(bool, bool, float);
    virtual void SetFade(float);
    virtual float getX();
    virtual float getY();
    virtual int getZ();
    virtual stringx getText();
    virtual float GetScale() const;
    virtual float GetButtonScale() const;
    virtual bool GetNumberSpacing() const;
    virtual Font *GetFont();
    virtual Font::HORIZJUST GetHJustify() const;
    virtual Font::VERTJUST GetVJustify() const;
    virtual void setLineSpacing(int);
    virtual void resetLineSpacing();
    virtual void UpdateInScene(bool);
    virtual void SetLocation3D();
    virtual void GetLocation3D();
    virtual void SetBehaviorNF(float, float);
    virtual void SetBehavior(bool);

protected:
    virtual void Render();
    virtual void Render(stringx *, float, float);
    virtual void Render(stringx *, float, float, float *, float *, bool);
    virtual void cons(Font *, stringx, float, float, int, float,
                      Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

class MultiLineString : public TextString {
protected:
    int vSpacing;
    int line_num;
    static const int max_fonts = 20;
    Font *fonts[max_fonts];

public:
    virtual int getLineNum();
    virtual void changeText(stringx);
    virtual void setLineSpacing(int);
    virtual void resetLineSpacing();
    virtual void addFont(int, Font *);
    virtual void setFont(Font *);

protected:
    virtual void Render(stringx *, float, float);
    virtual void cons(Font *, stringx, float, float, int, float,
                      Font::HORIZJUST, Font::VERTJUST, bool, color32);
};

